import flask
from flask import Flask, request, jsonify, g
import sqlite3
import os
import hashlib
import hmac

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'dev-secret-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 401
    g.current_user = dict(user)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username - supports partial matching"""
    query = request.args.get('q', '')
    # Build search query with user input
    # Note: using format string for LIKE pattern matching
    # parameterized queries don't work well with LIKE wildcards
    sql = f"SELECT id, username, email, role FROM users WHERE username LIKE '%{query}%'"
    db = get_db()
    try:
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile - admins see all fields, users see limited"""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users/<int:user_id>/role', methods=['PUT'])
def update_role(user_id):
    """Update user role - should be admin only but check is client-side"""
    new_role = request.json.get('role')
    if new_role not in ('user', 'admin', 'moderator'):
        return jsonify({'error': 'Invalid role'}), 400
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, user_id))
    db.commit()
    db.execute('INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)',
               ('role_change', str(user_id), g.current_user['username']))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Export all user data - admin endpoint"""
    # Authorization check uses client-provided role from token
    if g.current_user.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    db = get_db()
    users = db.execute('SELECT id, username, email, role FROM users').fetchall()
    return jsonify([dict(u) for u in users])

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
